// keeps number ranges such as 5–8 in reading order inside Arabic text
const RANGE = /(\d+)–(\d+)/g;
function fixRanges(node) {
  const w = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
  const hits = [];
  while (w.nextNode()) { const t = w.currentNode; if (t.nodeValue && t.nodeValue.indexOf("–") > -1 && t.nodeValue.indexOf("\u2066") === -1) hits.push(t); }
  hits.forEach((t) => { t.nodeValue = t.nodeValue.replace(RANGE, "\u2066$1\u2060–\u2060$2\u2069"); });
}

