// joints: 0 head,1 neck,2 hip,3 eL,4 hL,5 eR,6 hR,7 kL,8 fL,9 kR,10 fR   (L = near side, R = far side)
const swap=p=>{const o=p.slice();[[3,5],[4,6],[7,9],[8,10]].forEach(([a,b])=>{o[a*2]=p[b*2];o[a*2+1]=p[b*2+1];o[b*2]=p[a*2];o[b*2+1]=p[a*2+1];});return o;};
const mirror=p=>p.map((v,i)=>i%2?v:200-v);
const withArms=(p,a)=>{const o=p.slice();for(let i=0;i<8;i++)o[6+i]=a[i];return o;};
// Every pose is rebuilt with fixed segment lengths so limbs never stretch; grounded poses are dropped onto the floor line.
function norm(p0,ground){
  const p=p0.slice();
  const dir=(a,b)=>{const dx=p0[b*2]-p0[a*2],dy=p0[b*2+1]-p0[a*2+1],d=Math.hypot(dx,dy)||1;return[dx/d,dy/d];};
  const set=(b,a,d,L)=>{p[b*2]=p[a*2]+d[0]*L;p[b*2+1]=p[a*2+1]+d[1]*L;};
  const D=[dir(2,1),dir(1,0),dir(1,3),dir(3,4),dir(1,5),dir(5,6),dir(2,7),dir(7,8),dir(2,9),dir(9,10)];
  set(1,2,D[0],50);set(0,1,D[1],14);set(3,1,D[2],25);set(4,3,D[3],22);set(5,1,D[4],25);set(6,5,D[5],22);set(7,2,D[6],35);set(8,7,D[7],35);set(9,2,D[8],35);set(10,9,D[9],35);
  let low=Math.max(p[17],p[21]);if(ground==="hands")low=Math.max(low,p[9],p[13]);
  if(ground||low>180){const sft=180-low;for(let i=1;i<22;i+=2)p[i]+=sft;}
  return p;
}

