const SEG=[[2,1,50],[1,0,14],[1,3,25],[3,4,22],[1,5,25],[5,6,22],[2,7,35],[7,8,35],[2,9,35],[9,10,35]];
const toAng=p=>({x:p[4],y:p[5],a:SEG.map(([a,b])=>Math.atan2(p[b*2+1]-p[a*2+1],p[b*2]-p[a*2]))});
function fromAng(A){const p=new Array(22);p[4]=A.x;p[5]=A.y;SEG.forEach(([a,b,L],i)=>{p[b*2]=p[a*2]+Math.cos(A.a[i])*L;p[b*2+1]=p[a*2+1]+Math.sin(A.a[i])*L;});return p;}
function lerpA(A,B,u){return{x:A.x+(B.x-A.x)*u,y:A.y+(B.y-A.y)*u,a:A.a.map((v,i)=>{let d=B.a[i]-v;while(d>Math.PI)d-=2*Math.PI;while(d<-Math.PI)d+=2*Math.PI;return v+d*u;})};}
const lowOf=(p,hands)=>{let l=Math.max(p[17],p[21]);if(hands)l=Math.max(l,p[9],p[13]);return l;};
function tween(mv,a,b,u){
  const p=fromAng(lerpA(a.A,b.A,u));const low=lowOf(p,mv.hands);
  if((a.g&&b.g)||low>180){const sft=180-low;for(let i=1;i<22;i+=2)p[i]+=sft;}
  return p;
}
MOVES.bear.hands=1;
for(const k in MOVES)MOVES[k].frames.forEach(f=>{if(f.bj)f.ball=[f.p[f.bj[0]*2]+f.bj[1],f.p[f.bj[0]*2+1]+f.bj[2]];f.A=toAng(f.p);f.g=lowOf(f.p,MOVES[k].hands)>=179;});
/* ---------- figure engine ---------- */
const el=(n,a,p)=>{const e=document.createElementNS(NS,n);for(const k in a)e.setAttribute(k,a[k]);if(p)p.appendChild(e);return e;};
const reduce=window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches;
function Figure(host){
  host.innerHTML="";
  const cap=document.createElement("div");cap.className="cap";cap.innerHTML='<span class="nm"></span><span class="ph" hidden></span>';
  const svg=el("svg",{viewBox:"0 -52 200 254",role:"img"});
  host.appendChild(svg);host.appendChild(cap);
  const ticks=el("g",{},svg);const tk=[];for(let i=0;i<7;i++)tk.push(el("line",{y1:191,y2:191,stroke:"#3a4e85","stroke-width":3,"stroke-linecap":"round"},ticks));
  el("line",{x1:-10,y1:184,x2:210,y2:184,stroke:"#C7CED9","stroke-width":2,"stroke-linecap":"round",opacity:.7},svg);
  const bar=el("line",{x1:58,y1:9,x2:142,y2:9,stroke:"#E7B53C","stroke-width":5,"stroke-linecap":"round"},svg);
  const g=el("g",{},svg);
  const sh=el("ellipse",{cy:186,rx:22,ry:3.5,fill:"#14214a"},g);
  const mk=(c,w)=>el("polyline",{fill:"none",stroke:c,"stroke-width":w,"stroke-linecap":"round","stroke-linejoin":"round"},g);
  const farLeg=mk("#8fa3d6",8),farArm=mk("#8fa3d6",7),torso=mk("#fff",10),nearLeg=mk("#fff",8),nearArm=mk("#fff",7);
  const head=el("circle",{r:11,fill:"#fff"},g);
  const ball=el("circle",{r:7.5,fill:"#4DA8FF",stroke:"#fff","stroke-width":1.5},g);
  const hls=[0,1,2].map(()=>el("circle",{r:13,fill:"none",stroke:"#E7B53C","stroke-width":3,opacity:0},g));
  const pt=(p,i)=>p[i*2].toFixed(1)+","+p[i*2+1].toFixed(1);
  const st={mv:null,i:0,t:0,playing:!reduce,speed:1,last:0,off:0,hold:null};
  const self={st,onPhase:null};
  function draw(p,ballP,dx){
    g.setAttribute("transform","translate("+(dx||0).toFixed(1)+",0)");
    farLeg.setAttribute("points",[pt(p,2),pt(p,9),pt(p,10)].join(" "));
    farArm.setAttribute("points",[pt(p,1),pt(p,5),pt(p,6)].join(" "));
    torso.setAttribute("points",[pt(p,1),pt(p,2)].join(" "));
    nearLeg.setAttribute("points",[pt(p,2),pt(p,7),pt(p,8)].join(" "));
    nearArm.setAttribute("points",[pt(p,1),pt(p,3),pt(p,4)].join(" "));
    head.setAttribute("cx",p[0]);head.setAttribute("cy",p[1]);
    const low=Math.max(p[17],p[21]);const s=Math.max(.45,1-(180-low)/90);
    sh.setAttribute("cx",p[4]);sh.setAttribute("rx",(22*s).toFixed(1));
    if(ballP){ball.setAttribute("cx",ballP[0]);ball.setAttribute("cy",ballP[1]);ball.style.display="";}else ball.style.display="none";
    self.cur=p;
  }
  function setHL(idx,p){hls.forEach((h,k)=>{if(idx&&idx[k]!=null){h.setAttribute("cx",p[idx[k]*2]);h.setAttribute("cy",p[idx[k]*2+1]);h.setAttribute("opacity",1);}else h.setAttribute("opacity",0);});}
  const ease=t=>t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2;
  function frame(now){
    if(dead||!svg.isConnected)return;
    if(!st.mv){requestAnimationFrame(frame);return;}
    const dt=Math.min(60,now-st.last);st.last=now;
    const F=st.mv.frames;
    if(st.hold!=null){
      const f=F[st.hold.f];draw(f.p,f.ball,f.dx);setHL(st.hold.hl,f.p);
      const k=1+.12*Math.sin(now/180);hls.forEach(h=>h.setAttribute("r",(13*k).toFixed(1)));
    }else{
      if(st.playing){st.t+=dt*st.speed;
        while(st.t>=F[st.i].ms){st.t-=F[st.i].ms;st.i=(st.i+1)%F.length;if(self.onFrame)self.onFrame(st.i);}
        if(st.mv.scroll)st.off=(st.off+dt*st.speed*.09*st.mv.scroll+34)%34;}
      const a=F[st.i],b=F[(st.i+1)%F.length],u=a.cut?0:ease(st.t/a.ms);
      const p=tween(st.mv,a,b,u);
      const bp=(a.bj&&b.bj)?[p[a.bj[0]*2]+a.bj[1]+(b.bj[1]-a.bj[1])*u,p[a.bj[0]*2+1]+a.bj[2]+(b.bj[2]-a.bj[2])*u]:(a.ball&&b.ball?[a.ball[0]+(b.ball[0]-a.ball[0])*u,a.ball[1]+(b.ball[1]-a.ball[1])*u]:(a.ball||null));
      const wrap=(st.i+1)%F.length===0&&a.ball&&b.ball&&Math.abs(a.ball[0]-b.ball[0])>90;
      draw(p,wrap?a.ball:bp,(a.dx||0)+((b.dx||0)-(a.dx||0))*u);setHL(null);
    }
    tk.forEach((l,k)=>{const x=-20+k*34-st.off;l.setAttribute("x1",x);l.setAttribute("x2",x+12);});
    ticks.style.display=st.mv.scroll?"":"none";bar.style.display=st.mv.prop==="bar"?"":"none";
    requestAnimationFrame(frame);
  }
  self.load=(id)=>{st.mv=MOVES[id];st.i=0;st.t=0;st.hold=null;cap.querySelector(".nm").textContent=st.mv.name;self.phaseLabel(null);};
  self.hold=(ph)=>{st.hold=ph;self.phaseLabel(ph?ph.t:null);};
  self.phaseLabel=(t)=>{const e=cap.querySelector(".ph");if(t){e.textContent=t;e.hidden=false;}else e.hidden=true;};
  st.last=performance.now();requestAnimationFrame(frame);
  return self;
}

/* ---------- mini pitch for endurance ---------- */
function Pitch(host){
  host.innerHTML="";
  const svg=el("svg",{viewBox:"0 0 300 170",role:"img"});host.appendChild(svg);
  el("rect",{x:14,y:14,width:272,height:142,rx:10,fill:"none",stroke:"#C7CED9","stroke-width":2},svg);
  el("line",{x1:150,y1:14,x2:150,y2:156,stroke:"#3a4e85","stroke-width":2},svg);
  el("rect",{x:6,y:65,width:8,height:40,fill:"#fff"},svg);el("rect",{x:286,y:65,width:8,height:40,fill:"#fff"},svg);
  const ds=[];for(let i=0;i<6;i++)ds.push(el("circle",{r:8,fill:i<3?"#fff":"#4DA8FF"},svg));
  const b=el("circle",{r:4.5,fill:"#E7B53C"},svg);
  [130,150,170].forEach(x=>el("circle",{cx:x,cy:164,r:3,fill:"#E7B53C"},svg));
  let on=true;
  (function tick(t){ if(on&&!reduce){const s=t/900;
    ds.forEach((d,i)=>{const cx=(i<3?95:205)+Math.sin(s*(.7+i*.13)+i*2)*62,cy=85+Math.cos(s*(.9+i*.11)+i)*48;d.setAttribute("cx",cx);d.setAttribute("cy",cy);});
    b.setAttribute("cx",150+Math.sin(s*1.3)*110);b.setAttribute("cy",85+Math.sin(s*2.1)*50);}
    else ds.forEach((d,i)=>{d.setAttribute("cx",(i<3?70:190)+ (i%3)*30);d.setAttribute("cy",50+(i%3)*35);});
    if(host.isConnected)requestAnimationFrame(tick);})(0);
  return {stop:()=>{on=false;}};
}

